import sys
import math

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, m):
    gcd, x, _ = extended_gcd(a % m, m)
    if gcd != 1:
        return None
    return (x % m + m) % m

def chinese_remainder_theorem(r, m):
    if not r:
        return 0

    n = len(r)
    result = r[0] % m[0]
    current_m = m[0]

    for i in range(1, n):
        ri = r[i] % m[i]
        mi = m[i]

        diff = (ri - result) % mi
        g = math.gcd(current_m, mi)

        if diff % g != 0:
            return -1

        new_m = current_m // g
        inv = mod_inverse(current_m // g, mi // g)

        if inv is None:
            return -1

        step = (diff // g) * inv % (mi // g)
        result = (result + step * current_m) % (current_m * mi // g)
        current_m = current_m * mi // g

    return result

def main():
    line = sys.stdin.readline().strip()

    r = []
    m = []

    i = 0
    while i < len(line):
