            nums = []
            j = i + 1
            while j < len(line) and line[j] != ']':
                if line[j].isdigit() or (line[j] == '-' and j + 1 < len(line) and line[j + 1].isdigit()):
                    num_str = ''
                    while j < len(line) and (line[j].isdigit() or line[j] == '-'):
                        num_str += line[j]
                        j += 1
                    nums.append(int(num_str))
                else:
